prompt --application/shared_components/security/authentications/trader_auth
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(6511671877896747)
,p_name=>'trader_auth'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attribute_03=>'trader_auth'
,p_attribute_05=>'N'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION trader_auth(',
'  p_username IN VARCHAR2,',
'  p_password IN VARCHAR2',
') RETURN BOOLEAN IS',
'  v_count  NUMBER;',
'  v_trader_id NUMBER;',
'BEGIN',
'  SELECT COUNT(*), MAX(t.TRADER_ID)',
'  INTO v_count, v_trader_id',
'  FROM "USER" u',
'  JOIN TRADER t ON t.USER_ID = u.USER_ID',
'  WHERE LOWER(u.EMAIL) = LOWER(p_username)',
'    AND u.PASSWORD = p_password',
'    AND u.ROLE = ''TRADER''',
'    AND u.STATUS = ''ACTIVE'';',
'',
'  IF v_count > 0 THEN',
'    apex_custom_auth.set_user(',
'      p_user => TO_CHAR(v_trader_id)',
'    );',
'  END IF;',
'',
'  RETURN v_count > 0;',
'END;'))
,p_invalid_session_type=>'LOGIN'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>5041803
);
end;
