prompt --application/pages/page_00001
begin
wwv_flow_imp_page.create_page(
 p_id=>1
,p_name=>'Trader Report'
,p_alias=>'TRADER-REPORT1'
,p_step_title=>'Trader Report'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$(document).ready(function() {',
'  setTimeout(function() {',
'',
'    function showPeriod(period) {',
'      $(''#weekly-region'').hide();',
'      $(''#monthly-region'').hide();',
'      $(''#yearly-region'').hide();',
'      $(''#slot-region'').hide();',
'      $(''#daily-region'').hide();',
'      $(''#stock-region'').hide();',
'',
'      $(''button[data-period]'').css({',
'        ''background'': ''white'',',
'        ''color'': ''#eb4b3f''',
'      });',
'',
'      if(period === ''WEEKLY'') $(''#weekly-region'').show();',
'      if(period === ''MONTHLY'') $(''#monthly-region'').show();',
'      if(period === ''YEARLY'') $(''#yearly-region'').show();',
'      if(period === ''SLOTS'') $(''#slot-region'').show();',
'      if(period === ''DAILY'') $(''#daily-region'').show();',
'      if(period === ''STOCK'') $(''#stock-region'').show();',
'',
'      $(''button[data-period="'' + period + ''"]'').css({',
'        ''background'': ''linear-gradient(90deg, #eb4b3f, #f0945b)'',',
'        ''color'': ''white''',
'      });',
'',
'      apex.server.process(''GET_KPI'', {',
'        x01: period',
'      }, {',
'        success: function(data) {',
unistr('          $(''#kpi-revenue'').text(''\00A3'' + data.revenue);'),
'          $(''#kpi-orders'').text(data.orders);',
unistr('          $(''#kpi-avg'').text(''\00A3'' + data.avg);'),
'        }',
'      });',
'    }',
'',
'    showPeriod(''DAILY'');',
'',
'    $(document).on(''click'', ''button[data-period]'', function() {',
'      showPeriod($(this).data(''period''));',
'    });',
'',
'  }, 500);',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('/* \2500\2500 Top Nav Orange \2500\2500 */'),
'.t-Header {',
'  background: linear-gradient(90deg, #eb4b3f, #f0945b) !important;',
'}',
'.t-Header-appName, .t-Header-appName a {',
'  color: white !important;',
'  font-weight: 700 !important;',
