wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(6514682150324703)
,p_plug_name=>'Collection Slots'
,p_region_name=>'slot-region'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    cs.SLOT_DATE,',
'    cs.SLOT_DAY,',
'    cs.SLOT_LABEL AS TIME_SLOT,',
'    COUNT(o.ORDER_ID) AS ORDERS_BOOKED,',
'    cs.CAPACITY AS MAX_CAPACITY,',
'    cs.CAPACITY - COUNT(o.ORDER_ID) AS REMAINING_SPOTS,',
'    NVL(SUM(o.TOTAL_AMOUNT), 0) AS SLOT_REVENUE',
'FROM COLLECTION_SLOT cs',
'LEFT JOIN "ORDER" o',
'    ON o.COLLECTION_SLOT_ID = cs.COLLECTION_SLOT_ID',
'    AND o.ORDER_STATUS IN (''PLACED'', ''COLLECTED'')',
'JOIN SHOP s ON s.SHOP_ID = cs.SHOP_ID',
'JOIN TRADER t ON t.TRADER_ID = s.TRADER_ID',
'JOIN "USER" u ON u.USER_ID = t.USER_ID',
'WHERE UPPER(u.EMAIL) = :APP_USER',
'AND cs.IS_ACTIVE = ''Y''',
'AND cs.SLOT_DATE >= TRUNC(SYSDATE)',
'GROUP BY',
'    cs.COLLECTION_SLOT_ID,',
'    cs.SLOT_DATE,',
'    cs.SLOT_DAY,',
'    cs.SLOT_LABEL,',
'    cs.CAPACITY,',
'    cs.START_TIME',
'ORDER BY cs.SLOT_DATE, cs.START_TIME'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
