wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(6515628462324713)
,p_plug_name=>'Daily Orders'
,p_region_name=>'daily-region'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>60
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    o.ORDER_ID,',
'    cs.SLOT_DATE,',
'    cs.SLOT_DAY,',
'    cs.SLOT_LABEL AS COLLECTION_SLOT,',
'    p.PRODUCT_NAME,',
'    oi.QUANTITY,',
'    oi.UNIT_PRICE,',
'    oi.LINE_TOTAL,',
'    o.ORDER_STATUS',
'FROM "ORDER" o',
'JOIN ORDER_ITEM oi ON oi.ORDER_ID = o.ORDER_ID',
'JOIN PRODUCT p ON p.PRODUCT_ID = oi.PRODUCT_ID',
'JOIN COLLECTION_SLOT cs ON cs.COLLECTION_SLOT_ID = o.COLLECTION_SLOT_ID',
'JOIN SHOP s ON s.SHOP_ID = o.SHOP_ID',
'JOIN TRADER t ON t.TRADER_ID = s.TRADER_ID',
'JOIN "USER" u ON u.USER_ID = t.USER_ID',
'WHERE UPPER(u.EMAIL) = :APP_USER',
'AND TRUNC(o.ORDER_DATE) >= TRUNC(SYSDATE) - 1',
'AND o.ORDER_STATUS IN (''PLACED'', ''COLLECTED'')',
'ORDER BY cs.SLOT_DATE, cs.START_TIME'))
