wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11053818794804246)
,p_plug_name=>'Weekly Sales'
,p_title=>'Weekly Sales'
,p_region_name=>'weekly-region'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    TRUNC(o.ORDER_DATE, ''IW'') AS WEEK_START,',
'    TRUNC(o.ORDER_DATE, ''IW'') + 6 AS WEEK_END,',
'    COUNT(DISTINCT o.ORDER_ID) AS TOTAL_ORDERS,',
'    SUM(o.ORDER_AMOUNT) AS GROSS_SALES,',
'    SUM(o.DISCOUNT_AMOUNT) AS TOTAL_DISCOUNTS,',
'    SUM(o.TOTAL_AMOUNT) AS NET_REVENUE',
'FROM "ORDER" o',
'JOIN SHOP s ON s.SHOP_ID = o.SHOP_ID',
'JOIN TRADER t ON t.TRADER_ID = s.TRADER_ID',
'JOIN "USER" u ON u.USER_ID = t.USER_ID',
'WHERE o.ORDER_STATUS IN (''PLACED'', ''COLLECTED'')',
'AND UPPER(u.EMAIL) = :APP_USER',
'AND o.ORDER_DATE >= TRUNC(SYSDATE, ''IW'') - 84',
'GROUP BY TRUNC(o.ORDER_DATE, ''IW'')',
'ORDER BY WEEK_START DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
