wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6530808550435989)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get KPI Values'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_start DATE;',
'BEGIN',
'  IF :P1_PERIOD = ''WEEKLY'' THEN',
'    v_start := TRUNC(SYSDATE, ''IW'');',
'  ELSIF :P1_PERIOD = ''MONTHLY'' THEN',
'    v_start := TRUNC(SYSDATE, ''MM'');',
'  ELSIF :P1_PERIOD = ''YEARLY'' THEN',
'    v_start := TRUNC(SYSDATE, ''YYYY'');',
'  ELSE',
'    v_start := TRUNC(SYSDATE, ''IW'');',
'  END IF;',
'',
'  SELECT ',
'    TO_CHAR(NVL(SUM(TOTAL_AMOUNT), 0), ''FM999,999.00''),',
'    NVL(COUNT(ORDER_ID), 0),',
'    TO_CHAR(NVL(AVG(TOTAL_AMOUNT), 0), ''FM999,999.00''),',
'    COUNT(DISTINCT CUSTOMER_ID)',
'  INTO ',
'    :P1_TOTAL_REVENUE,',
'    :P1_TOTAL_ORDERS,',
'    :P1_AVG_ORDER,',
'    :P1_TOTAL_CUSTOMERS',
'  FROM "ORDER"',
'  WHERE ORDER_STATUS IN (''PLACED'', ''COLLECTED'')',
'  AND TRUNC(ORDER_DATE) >= v_start;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6530808550435989
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6531268430435990)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_KPI'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_start DATE;',
'  v_end DATE;',
'  v_revenue VARCHAR2(50);',
'  v_orders NUMBER;',
'  v_avg VARCHAR2(50);',
'  v_customers NUMBER;',
'BEGIN',
'  v_end := SYSDATE;',
'  ',
'  IF apex_application.g_x01 = ''WEEKLY'' THEN',
'    v_start := TRUNC(SYSDATE, ''IW'');',
'  ELSIF apex_application.g_x01 = ''MONTHLY'' THEN',
'    v_start := TRUNC(SYSDATE, ''MM'');',
'  ELSIF apex_application.g_x01 = ''YEARLY'' THEN',
'    v_start := TRUNC(SYSDATE, ''YYYY'');',
'  ELSIF apex_application.g_x01 = ''DAILY'' THEN',
'    v_start := TRUNC(SYSDATE);',
'  ELSE',
'    v_start := TRUNC(SYSDATE, ''IW'');',
'  END IF;',
'',
'  SELECT',
'    TO_CHAR(NVL(SUM(o.TOTAL_AMOUNT), 0), ''FM999,999.00''),',
'    NVL(COUNT(DISTINCT o.ORDER_ID), 0),',
'    TO_CHAR(NVL(AVG(o.TOTAL_AMOUNT), 0), ''FM999,999.00''),',
'    COUNT(DISTINCT o.CUSTOMER_ID)',
'  INTO v_revenue, v_orders, v_avg, v_customers',
'  FROM "ORDER" o',
'  JOIN SHOP s ON s.SHOP_ID = o.SHOP_ID',
'  JOIN TRADER t ON t.TRADER_ID = s.TRADER_ID',
'  JOIN "USER" u ON u.USER_ID = t.USER_ID',
'  WHERE o.ORDER_STATUS IN (''PLACED'', ''COLLECTED'')',
'  AND UPPER(u.EMAIL) = :APP_USER',
'  AND TRUNC(o.ORDER_DATE) >= v_start;',
'',
'  apex_json.open_object;',
'  apex_json.write(''revenue'', v_revenue);',
'  apex_json.write(''orders'', v_orders);',
'  apex_json.write(''avg'', v_avg);',
'  apex_json.write(''customers'', v_customers);',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6531268430435990
);
end;
